<?php
declare(strict_types=1);
namespace Leikwan\Master\Support;
function fail(string $message): never { fwrite(STDERR, $message . PHP_EOL); exit(1); }
$repoRoot = dirname(__DIR__, 2);
require_once $repoRoot . '/master/src/Support/LeigodOnlyCanaryCampaignService.php';
final class CohortGate { public int $calls=0; public array $result=['ok'=>true,'promotion_ready'=>true,'policy_state'=>['outcome'=>'single_leg_only'],'artifact_gate'=>['ok'=>true],'capability_state'=>['ok'=>true]]; public function gate(object $ctx): array { $this->calls++; return $this->result; } }
final class CohortMutator { public int $calls=0; public function activate(array $request): void { $this->calls++; } }
function slave(int $node, array $p=[]): array { return array_replace(['node_id'=>$node,'endpoint_id'=>100+$node,'usable'=>true],$p); }
$gate=new CohortGate(); $mutator=new CohortMutator(); $svc=new LeigodOnlyCanaryCampaignService(new class {}, $gate, $mutator);
$pred0=['cohort'=>0,'scope'=>'global','status'=>'success','observing'=>false,'blockers'=>[]];
$pred1=['cohort'=>1,'scope'=>'global','status'=>'success','observing'=>false,'blockers'=>[]];
$r=$svc->evaluateForward(['scope'=>'global','cohort'=>0],['forward_id'=>1,'platform_family'=>'linux','slaves'=>[slave(1)]]); if(($r['write_mode']??'')!=='read_only'||$mutator->calls!==0) fail('cohort 0 must be read-only and never call activation mutators');
$r=$svc->evaluateForward(['scope'=>'global','cohort'=>1,'predecessor_snapshot'=>$pred0],['forward_id'=>2,'platform_family'=>'linux','leg_policy'=>'shared','slaves'=>[slave(1)]]); if(!($r['promotion_ready']??false)) fail('cohort 1 one usable shared slave should promote: '.json_encode($r));
$r=$svc->evaluateForward(['scope'=>'global','cohort'=>1,'predecessor_snapshot'=>$pred0],['forward_id'=>3,'platform_family'=>'linux','leg_policy'=>'shared','slaves'=>[slave(1),slave(2)]]); if(($r['promotion_ready']??false)||!in_array('cohort1_requires_exactly_one_usable_slave',$r['blockers']??[],true)) fail('cohort 1 must reject multiple slaves: '.json_encode($r));
$r=$svc->evaluateForward(['scope'=>'global','cohort'=>1,'predecessor_snapshot'=>$pred0],['forward_id'=>4,'platform_family'=>'linux','leg_policy'=>'dedicated','slaves'=>[slave(1)]]); if(($r['promotion_ready']??false)||!in_array('cohort1_requires_shared_leg_policy',$r['blockers']??[],true)) fail('cohort 1 must require shared leg policy');
$r=$svc->evaluateForward(['scope'=>'global','cohort'=>2,'predecessor_snapshot'=>$pred1],['forward_id'=>5,'platform_family'=>'linux','slaves'=>[slave(1),slave(2),slave(3)]]); if(!($r['promotion_ready']??false)) fail('cohort 2 distinct 2..8 slaves should promote: '.json_encode($r));
$r=$svc->evaluateForward(['scope'=>'global','cohort'=>2,'predecessor_snapshot'=>$pred1],['forward_id'=>6,'platform_family'=>'linux','slaves'=>[slave(1),slave(1)]]); if(($r['promotion_ready']??false)||!in_array('cohort2_requires_distinct_slave_nodes',$r['blockers']??[],true)) fail('cohort 2 same-node-only not ready');
foreach(['route_drift'=>'route_static_drift','static_drift'=>'route_static_drift','basecontroller_drift'=>'basecontroller_drift','pin_drift'=>'artifact_pin_drift','capability_drift'=>'capability_drift'] as $field=>$blocker){ $r=$svc->evaluateForward(['scope'=>'global','cohort'=>2,'predecessor_snapshot'=>$pred1],['forward_id'=>7,'platform_family'=>'linux','slaves'=>[slave(1),slave(2)],$field=>true]); if(($r['promotion_ready']??false)||!in_array($blocker,$r['blockers']??[],true)) fail($field.' should block cohort 2: '.json_encode($r)); }
foreach([3,4] as $cohort){ $predPrev=['cohort'=>$cohort-1,'scope'=>'global','status'=>'success','observing'=>false,'blockers'=>[]]; $r=$svc->evaluateForward(['scope'=>'global','cohort'=>$cohort,'predecessor_snapshot'=>$predPrev],['forward_id'=>8,'platform_family'=>'linux','slaves'=>[slave(1),slave(2)]]); if(($r['promotion_ready']??false)||!in_array('owner_approval_checkpoint_required',$r['blockers']??[],true)) fail('cohort '.$cohort.' requires owner approval'); $r=$svc->evaluateForward(['scope'=>'global','cohort'=>$cohort,'predecessor_snapshot'=>$predPrev,'owner_approved'=>true],['forward_id'=>8,'platform_family'=>'linux','slaves'=>[slave(1),slave(2)]]); if(!($r['promotion_ready']??false)) fail('cohort '.$cohort.' owner approval should allow ready'); }
$gate->result=['ok'=>false,'promotion_ready'=>false,'blockers'=>['upload_gate_failed'],'policy_state'=>['outcome'=>'speed_plus_eligible']]; $r=$svc->evaluateForward(['scope'=>'global','cohort'=>2,'predecessor_snapshot'=>$pred1],['forward_id'=>9,'platform_family'=>'linux','slaves'=>[slave(1),slave(2)]]); if(($r['promotion_ready']??false)||!in_array('upload_gate_failed',$r['blockers']??[],true)) fail('cohort status must consume activation gate per forward');
echo "ok\n";
